package com.sdkwork.clawrouter.app.model;


public class RoutingModelStats {
    private String lat;
    private String m;
    private String req;
    private String sr;
    private String tok;

    public String getLat() {
        return this.lat;
    }

    public void setLat(String lat) {
        this.lat = lat;
    }

    public String getM() {
        return this.m;
    }

    public void setM(String m) {
        this.m = m;
    }

    public String getReq() {
        return this.req;
    }

    public void setReq(String req) {
        this.req = req;
    }

    public String getSr() {
        return this.sr;
    }

    public void setSr(String sr) {
        this.sr = sr;
    }

    public String getTok() {
        return this.tok;
    }

    public void setTok(String tok) {
        this.tok = tok;
    }
}
